// The fonts this frame has, a page of them at a time, each name in its own
// face, and a specimen of the one picked: a big "Aa", a pangram at three
// sizes, the alphabet, figures, accents, Greek and Cyrillic.
//
// The fonts are the files in the frame's fonts folder (frameos.listAssets):
// on a Pi what a deploy copied there, on an ESP32 its SD card, where "Sync
// fonts" puts FrameOS's collection and every TrueType file is read where it
// lies, a page at a time (docs/esp32-fonts.md), so a page of a dozen faces
// costs the frame next to nothing. In the browser preview there are none but
// the built-in face. A face is named in the classes by its file
// (`font-[Galindo-Regular.ttf]`), which every runtime finds as it finds a
// family (`font-[Galindo]`).
//
// The font picked is the public `font` field (pick it here, or in the scene's
// settings); the page of the list is private.

const LIST_MS = 60 * 1000
const PANGRAM = 'Sphinx of black quartz, judge my vow.'
const LINES = [
  'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
  'abcdefghijklmnopqrstuvwxyz',
  '0123456789 &@#%?!()[]{}*+=/',
  'ÀÉÎÕÜ àéîõü ßçñ øå œæ ¿¡ €£',
  'Ελληνικά: Ωμέγα, άλφα, βήτα',
  'Кириллица: Жизнь, щука, ёж',
]

let listed = { at: 0, fonts: [] }

// The font files, the built-in face ("") first. Colour emoji fonts are
// bitmaps with no letters to show (and no outlines an ESP32 reads).
function fontsOf() {
  if (listed.at && Date.now() - listed.at < LIST_MS) return listed.fonts
  const files = []
  for (const path of frameos.listAssets('fonts', { shallow: true }) || []) {
    const name = path.replace(/^fonts\//, '')
    if (!/\.ttf$/i.test(name) || name.startsWith('.') || name.includes('/') || /emoji/i.test(name)) continue
    files.push(name)
  }
  files.sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()))
  listed = { at: Date.now(), fonts: [''].concat(files) }
  return listed.fonts
}

// "CormorantGaramond-BoldItalic.ttf" -> "Cormorant Garamond Bold Italic".
const words = (s) => s.replace(/([a-z0-9])([A-Z])/g, '$1 $2').replace(/([A-Z]+)([A-Z][a-z])/g, '$1 $2')
function label(file) {
  if (!file) return 'Ubuntu (built in)'
  return file
    .replace(/\.ttf$/i, '')
    .split(/[-_]/)
    .map(words)
    .join(' ')
}

// The classes that draw in a face: the file's own name, its spaces as
// underscores (a class has none).
const faceOf = (file) => (file ? `font-[${file.replace(/ /g, '_')}]` : '')

function looks(app) {
  const ink = app.frame.paper === true || app.frame.color === false
  return ink
    ? {
        page: 'bg-white text-black',
        bar: 'border-b-2 border-black',
        button: 'rounded-full border-2 border-black',
        row: 'rounded-lg',
        selected: 'rounded-lg bg-black text-white',
        muted: '',
        card: 'rounded-lg border-2 border-black',
      }
    : {
        page: 'bg-zinc-950 text-white',
        bar: 'border-b border-zinc-800',
        button: 'rounded-full bg-zinc-800 active:bg-zinc-600',
        row: 'rounded-lg active:bg-zinc-800',
        selected: 'rounded-lg bg-sky-600',
        muted: 'text-zinc-400',
        card: 'rounded-lg bg-zinc-900',
      }
}

export function get(app, context) {
  const own = looks(app)
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  const zoom = Math.max(0.75, Math.min(2.25, Math.round((Math.min(width, height) / 480) * 4) / 4))
  const px = (n) => `${Math.round(n * zoom)}px`
  const wide = width >= 600 * zoom

  const fonts = fontsOf()
  const picked = typeof app.state.font === 'string' && fonts.includes(app.state.font) ? app.state.font : ''
  if (context && context.round === true) return roundFonts(app, own, width, height, zoom, fonts, picked)
  // A narrow screen shows the list or the specimen: `page` -1 is the specimen.
  const listing = wide || Number(app.state.page) >= 0
  const rowHeight = Math.round(40 * zoom)
  const perPage = Math.max(3, Math.floor((height - Math.round(110 * zoom)) / rowHeight))
  const pages = Math.max(1, Math.ceil(fonts.length / perPage))
  const pageOfPicked = Math.floor(Math.max(0, fonts.indexOf(picked)) / perPage)
  const asked = Number(app.state.page)
  const page = Math.min(pages - 1, Math.max(0, Number.isFinite(asked) && asked >= 0 ? asked : pageOfPicked))
  const shown = fonts.slice(page * perPage, (page + 1) * perPage)

  const pick = (file) => {
    frameos.setState('font', file)
    if (!wide) frameos.setState('page', -1)
  }
  const turn = (by) => frameos.setState('page', Math.min(pages - 1, Math.max(0, page + by)))
  const button = `flex items-center justify-center h-[${px(34)}] px-[${px(16)}] text-[${px(15)}]`

  const list = (
    <div className={`flex flex-col ${wide ? `w-[${Math.round(width * 0.4)}px] shrink-0` : 'flex-1'} min-w-0 gap-[${px(2)}]`}>
      {shown.map((file) => (
        <div
          look={file === picked ? 'picked' : 'option'}
          className={`flex items-center h-[${rowHeight}px] px-[${px(10)}] ${file === picked ? own.selected : own.row}`}
          onClick={() => pick(file)}
        >
          <span className={`${faceOf(file)} text-[${px(19)}] truncate`}>{label(file)}</span>
        </div>
      ))}
      <div className="flex-1" />
      <div className={`flex items-center gap-[${px(8)}]`}>
        <div look="button" className={`${button} ${own.button}`} onClick={() => turn(-1)}>
          ‹
        </div>
        <span look="muted" className={`flex-1 text-center text-[${px(13)}] ${own.muted}`}>
          {`${page + 1} / ${pages} · ${fonts.length - 1} fonts`}
        </span>
        <div look="button" className={`${button} ${own.button}`} onClick={() => turn(1)}>
          ›
        </div>
      </div>
    </div>
  )

  const face = faceOf(picked)
  const specimen = (
    <div look="card" className={`flex flex-col flex-1 min-w-0 gap-[${px(6)}] p-[${px(14)}] ${own.card} overflow-hidden`}>
      <div className={`flex items-end gap-[${px(14)}]`}>
        <span className={`${face} text-[${px(92)}] leading-none`}>Aa</span>
        <div className="flex flex-col min-w-0 pb-[6px]">
          <span className={`text-[${px(17)}] font-bold whitespace-nowrap`}>{label(picked)}</span>
          <span look="muted" className={`text-[${px(12)}] whitespace-nowrap ${own.muted}`}>
            {picked || 'compiled into FrameOS'}
          </span>
        </div>
      </div>
      <span className={`${face} text-[${px(30)}] leading-tight`}>{PANGRAM}</span>
      <span className={`${face} text-[${px(20)}] leading-snug`}>{PANGRAM}</span>
      <span className={`${face} text-[${px(14)}]`}>{PANGRAM}</span>
      {LINES.map((line) => (
        <span className={`${face} text-[${px(18)}] truncate`}>{line}</span>
      ))}
    </div>
  )

  return (
    <div look="page" className={`flex flex-col w-full h-full ${own.page}`}>
      <div look="bar" className={`flex items-center h-[${px(48)}] px-[${px(14)}] gap-[${px(10)}] ${own.bar}`}>
        {!wide && !listing ? (
          <div look="button" className={`${button} ${own.button}`} onClick={() => frameos.setState('page', pageOfPicked)}>
            ‹ Fonts
          </div>
        ) : (
          <span className={`text-[${px(20)}] font-bold`}>Fonts</span>
        )}
        <div className="flex-1" />
        <span look="muted" className={`text-[${px(13)}] ${own.muted}`}>
          {fonts.length > 1 ? `${fonts.length - 1} on this frame` : 'only the built-in face here'}
        </span>
      </div>
      <div className={`flex flex-1 min-h-0 gap-[${px(14)}] p-[${px(12)}]`}>
        {wide || listing ? list : null}
        {wide || !listing ? specimen : null}
      </div>
    </div>
  )
}

// A round panel: the title in the arc at the top, the page's fonts as rows
// as wide as the circle is where each one is (the rows near the middle a
// little bigger), the page turns in the arc at the bottom; the specimen
// centred, its lines as wide as the circle lets them be.
function roundFonts(app, own, W, H, zoom, fonts, picked) {
  const px = (n) => `${Math.round(n * zoom)}px`
  const cx = W / 2, cy = H / 2, R = Math.min(W, H) / 2 - 12
  const chord = (dy) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
  const place = (top, height, width, cls, child, onClick = undefined) => (
    <div className={`absolute left-[${Math.round(cx - width / 2)}px] top-[${Math.round(cy + top)}px] w-[${width}px] h-[${height}px] ${cls}`} onClick={onClick}>{child}</div>
  )
  const button = `flex items-center justify-center h-[${px(34)}] px-[${px(16)}] text-[${px(15)}]`
  const listTop = -Math.round(R * 0.62)
  const listBottom = Math.round(R * 0.56)
  const rowHeight = Math.round(40 * zoom)
  const perPage = Math.max(3, Math.floor((listBottom - listTop) / rowHeight))
  const pages = Math.max(1, Math.ceil(fonts.length / perPage))
  const pageOfPicked = Math.floor(Math.max(0, fonts.indexOf(picked)) / perPage)
  const asked = Number(app.state.page)
  const listing = asked >= 0
  const page = Math.min(pages - 1, Math.max(0, Number.isFinite(asked) && asked >= 0 ? asked : pageOfPicked))
  const shown = fonts.slice(page * perPage, (page + 1) * perPage)
  const turn = (by) => frameos.setState('page', Math.min(pages - 1, Math.max(0, page + by)))
  const pick = (file) => {
    frameos.setState('font', file)
    frameos.setState('page', -1)
  }

  if (!listing) {
    const face = faceOf(picked)
    const top = -Math.round(R * 0.66)
    const bottom = Math.round(R * 0.8)
    return (
      <div look="page" className={`relative w-[${W}px] h-[${H}px] ${own.page}`}>
        {place(-Math.round(R * 0.9), Math.round(R * 0.9) + top, chord(R * 0.9), 'flex items-center justify-center',
          <div look="button" className={`${button} ${own.button}`} onClick={() => frameos.setState('page', pageOfPicked)}>
            ‹ Fonts
          </div>)}
        {place(top, bottom - top, chord(Math.max(-top, bottom)), `flex flex-col items-center gap-[${px(6)}] overflow-hidden text-center`,
          <>
            <span className={`${face} text-[${px(80)}] leading-none shrink-0`}>Aa</span>
            <span className={`text-[${px(17)}] font-bold truncate shrink-0`}>{label(picked)}</span>
            <span className={`${face} text-[${px(24)}] leading-tight shrink-0`}>{PANGRAM}</span>
            <span className={`${face} text-[${px(16)}] leading-snug shrink-0`}>{PANGRAM}</span>
            {LINES.slice(0, 2).map((line) => (
              <span className={`${face} text-[${px(16)}] truncate shrink-0`}>{line}</span>
            ))}
          </>)}
      </div>
    )
  }

  // The rows: heights weighted toward the middle, filling the list's room.
  const weights = shown.map((_, i) => {
    const t = shown.length > 1 ? (i / (shown.length - 1)) * 2 - 1 : 0
    return 1.2 - 0.35 * Math.abs(t)
  })
  const sum = weights.reduce((a, b) => a + b, 0)
  const room = Math.min(listBottom - listTop, Math.round(rowHeight * sum))
  let y = listTop + Math.round((listBottom - listTop - room) / 2)
  const rows = shown.map((file, i) => {
    const h = Math.round((room * weights[i]) / sum)
    const top = y
    y += h
    const w = chord(Math.max(Math.abs(top), Math.abs(top + h))) - 8
    return place(top, h - 2, w, `flex items-center justify-center px-[${px(10)}] ${file === picked ? own.selected : own.row}`,
      <span className={`${faceOf(file)} text-[${Math.round(h * 0.47)}px] truncate`}>{label(file)}</span>, () => pick(file))
  })
  const turnTop = listBottom + Math.round(8 * zoom)
  return (
    <div look="page" className={`relative w-[${W}px] h-[${H}px] ${own.page}`}>
      {place(-Math.round(R * 0.92), Math.round(R * 0.92) + listTop - 4, chord(R * 0.92), 'flex flex-col items-center justify-center',
        <>
          <span className={`text-[${px(20)}] font-bold`}>Fonts</span>
          <span look="muted" className={`text-[${px(13)}] ${own.muted}`}>
            {fonts.length > 1 ? `${fonts.length - 1} on this frame` : 'only the built-in face here'}
          </span>
        </>)}
      {rows}
      {place(turnTop, Math.round(34 * zoom), chord(turnTop + 34 * zoom), `flex items-center gap-[${px(8)}]`,
        <>
          <div look="button" className={`${button} ${own.button}`} onClick={() => turn(-1)}>‹</div>
          <span look="muted" className={`flex-1 text-center text-[${px(13)}] ${own.muted}`}>{`${page + 1} / ${pages}`}</span>
          <div look="button" className={`${button} ${own.button}`} onClick={() => turn(1)}>›</div>
        </>)}
    </div>
  )
}
